function s(r,n={}){if(!r)return"—";const t=new Date(r);if(isNaN(t))return"—";const o={day:"numeric",month:"short",year:"numeric"};return t.toLocaleDateString("en-IN",{...o,...n})}function i(r){if(!r)return"";const n=new Date(r);return isNaN(n)?"":n.toISOString().split("T")[0]}function u(r){if(!r)return"";const n=Math.floor((Date.now()-new Date(r))/1e3);if(n<60)return"just now";const t=Math.floor(n/60);if(t<60)return`${t}m ago`;const o=Math.floor(t/60);if(o<24)return`${o}h ago`;const e=Math.floor(o/24);if(e<30)return`${e}d ago`;const a=Math.floor(e/30);return a<12?`${a}mo ago`:`${Math.floor(a/12)}y ago`}function c(r){if(!r)return"";const n=Math.floor((Date.now()-new Date(r))/(1e3*60*60*24));if(n<1)return"Today";if(n===1)return"1 day";if(n<30)return`${n} days`;const t=Math.floor(n/30),o=n%30;if(t<12)return o>0?`${t}mo ${o}d`:`${t} months`;const e=Math.floor(t/12),a=t%12;return a>0?`${e}y ${a}mo`:`${e} year${e>1?"s":""}`}function f(r,n){const t=new Date(r);if(isNaN(t))return r;switch(n){case"1D":return t.toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"});case"1W":case"1M":return t.toLocaleDateString("en-IN",{day:"numeric",month:"short"});case"3M":case"6M":return t.toLocaleDateString("en-IN",{day:"numeric",month:"short"});case"1Y":return t.toLocaleDateString("en-IN",{month:"short",year:"2-digit"});case"5Y":return t.toLocaleDateString("en-IN",{month:"short",year:"numeric"});default:return t.toLocaleDateString("en-IN",{day:"numeric",month:"short"})}}export{f as a,u as b,s as f,c as h,i as t};
